validator:
function validate(input) {
  const [{ ProductPurchases = [], ProductInfo = [] }] = input;
  const products = new Set(), bought = new Set();
  for (const [id, category, price] of ProductInfo) {
    if ([id, category, price].includes(null)) return 'No value in ProductInfo may be null.';
    if (products.has(id)) return `product_id ${id} appears twice in ProductInfo.`;
    products.add(id);
  }
  for (const [user, product, quantity] of ProductPurchases) {
    if ([user, product, quantity].includes(null)) return 'No value in ProductPurchases may be null.';
    if (!products.has(product)) return `product_id ${product} is not in ProductInfo.`;
    if (!(quantity > 0)) return `quantity ${quantity} must be positive.`;
    const key = `${user}|${product}`;
    if (bought.has(key)) return `(${user}, ${product}) appears twice in ProductPurchases.`;
    bought.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const categories = ['Electronics', 'Books', 'Clothing', 'Kitchen', 'Sports', 'Toys', 'Garden'];
  const productCount = small ? 2 + Math.floor(rand() * 4) : 40;
  const ProductInfo = [];
  for (let i = 0; i < productCount; i++) ProductInfo.push([small ? 101 + i : 100 + i * 3, pick(categories), pick([20, 35, 50, 75, 100, 12.5])]);
  const users = small ? 6 : 400;
  // Most small cases hold 6 to 8 purchases, enough for one pair to reach three customers.
  const limit = small ? (rand() < 0.15 ? Math.floor(rand() * 6) : 6 + Math.floor(rand() * 3)) : 2000;
  const bought = new Set(), ProductPurchases = [];
  const buy = (user, product) => {
    const key = `${user}|${product}`;
    if (ProductPurchases.length >= limit || bought.has(key)) return;
    bought.add(key);
    ProductPurchases.push([user, product, 1 + Math.floor(rand() * 5)]);
  };
  if (small && rand() < 0.8) {
    // Plant one pair bought by 2 to 4 users, so its count lands just below, on or above the threshold of 3.
    const ids = shuffle(ProductInfo.map(p => p[0])), sharers = shuffle([1, 2, 3, 4, 5, 6]).slice(0, 2 + Math.floor(rand() * 3));
    for (const user of sharers) { buy(user, ids[0]); buy(user, ids[1]); }
  }
  // Popular products are drawn far more often, so pair counts spread out and some pairs share a count.
  const weights = ProductInfo.map((_, i) => 1 / (1 + i * (small ? 0.3 : 0.15)));
  const total = weights.reduce((a, b) => a + b, 0);
  const draw = () => { let r = rand() * total; for (let i = 0; i < weights.length; i++) { r -= weights[i]; if (r < 0) return ProductInfo[i][0]; } return ProductInfo.at(-1)[0]; };
  for (let tries = 0; ProductPurchases.length < limit && tries < limit * 5; tries++) buy(1 + Math.floor(rand() * users), draw());
  return [{ ProductPurchases: shuffle(ProductPurchases), ProductInfo: shuffle(ProductInfo) }];
}
